use vstd::prelude::*;

verus! {

    /// In-place replace all occurrences of `x` by `y` in the vector `v`.
    ///
    /// Post‐condition: the length of `v` is unchanged, and for each index `k` in
    /// the original vector
    ///     if old(v)[k] == x then v[k] == y
    ///     else              v[k] == old(v)[k]
    fn replace(v: &mut Vec<i32>, x: i32, y: i32)
        ensures
            // length is preserved
            v.len() == old(v).len(),
            // each entry is either replaced (if it was x) or unchanged
            forall |k: usize| k < v.len() ==>
                if old(v)[k] == x {
                    v[k] == y
                } else {
                    v[k] == old(v)[k]
                }
    {
        // Capture a ghost copy of the original contents
        ghost let orig: Vec<i32> = v.clone();

        let mut i: usize = 0;
        // Process each index in turn
        while i < v.len()
            invariant
                // loop index is within bounds
                i <= v.len(),
                // for all indices < i, we have already done the correct replacement
                forall |k: usize| k < i ==>
                    if orig[k] == x {
                        v[k] == y
                    } else {
                        v[k] == orig[k]
                    },
                // for all indices >= i, the vector still equals the original there
                forall |k: usize| i <= k && k < v.len() ==>
                    v[k] == orig[k],
            decreases v.len() - i,
        {
            if v[i] == x {
                v[i] = y;
            }
            i = i + 1;
        }
    }

}

